#!/usr/bin/env bash
# Writes deploy/staging/.env with random, staging-only secrets (never real ones).
# Refuses to overwrite an existing .env unless --force (that would lock you out of the
# existing database volume: run scripts/reset.sh --wipe afterwards).
set -euo pipefail
cd "$(dirname "$0")/.."

if [[ -f .env && "${1:-}" != "--force" ]]; then
  echo ".env already exists. Use --force to replace it (then wipe the volumes)." >&2
  exit 1
fi

rand_hex() { openssl rand -hex "$1"; }

cat > .env <<EOF
# Generated by scripts/init-env.sh on $(date -u +%Y-%m-%dT%H:%M:%SZ). Staging only. Do not commit.
DB_NAME=wisenquire_staging
DB_USERNAME=wisenquire
DB_PASSWORD=$(rand_hex 16)
DB_ROOT_PASSWORD=$(rand_hex 16)
JWT_SECRET=$(rand_hex 48)
SUPER_ADMIN_EMAIL=platform.admin@staging.wisenquire.invalid
SUPER_ADMIN_PASSWORD=$(rand_hex 12)
ADS_CREDENTIALS_ENCRYPTION_KEY=$(openssl rand -base64 32)
# Must be an exact https origin (ProductionSafetyConfiguration). The browser reaches staging
# same-origin through nginx, so this is only used for cross-origin callers.
ALLOWED_ORIGINS=https://staging.wisenquire.invalid
SMTP_PASSWORD=mailpit-accepts-any-$(rand_hex 4)
WHATSAPP_VERIFY_TOKEN=staging-verify-$(rand_hex 8)
S3_ACCESS_KEY=staging$(rand_hex 6)
S3_SECRET_KEY=$(rand_hex 20)
S3_BUCKET=wisenquire-staging
# Every seeded tenant user (personas) logs in with this password + the OTP from Mailpit.
SEED_USER_PASSWORD=Staging-$(rand_hex 6)
EOF
echo "Wrote $(pwd)/.env"
